<script setup>
import{computed,onMounted,ref}from"vue";import{useStore}from"vuex";import AdminService from"@/api/AdminService";import{getStoredToken}from"@/utils/storage";
const store=useStore(),loading=ref(true),partialError=ref(false),counts=ref({members:0,orders:0,products:0,pending:0}),recentOrders=ref([]);const adminName=computed(()=>store.state.user?.fullName||"관리자");const hour=new Date().getHours();const greeting=hour<12?"좋은 아침입니다":hour<18?"좋은 오후입니다":"오늘도 수고하셨습니다";const today=new Intl.DateTimeFormat("ko-KR",{year:"numeric",month:"long",day:"numeric",weekday:"short"}).format(new Date());
const metrics=computed(()=>[{label:"전체 회원",value:counts.value.members,unit:"명",help:"가입 회원 현황",to:"/admin/members",icon:"fa-regular fa-user",tone:"rose"},{label:"전체 주문",value:counts.value.orders,unit:"건",help:"누적 주문 현황",to:"/admin/orders",icon:"fa-solid fa-receipt",tone:"violet"},{label:"등록 상품",value:counts.value.products,unit:"개",help:"판매 상품 현황",to:"/admin/products",icon:"fa-solid fa-bottle-droplet",tone:"green"},{label:"취소 대기",value:counts.value.pending,unit:"건",help:"처리가 필요한 주문",to:"/admin/cancle",icon:"fa-solid fa-triangle-exclamation",tone:"amber"}]);
