const listOf=data=>Array.isArray(data)?data:data?.users||data?.orders||data?.products||data?.kits||[];const totalOf=data=>Number(data?.total??data?.totalCount??listOf(data).length);const formatNumber=value=>Number(value||0).toLocaleString("ko-KR");const statusTone=status=>status?.includes("완료")?"done":status?.includes("취소")?"danger":status?.includes("배송")?"shipping":"waiting";
const loadDashboard=async()=>{loading.value=true;partialError.value=false;const token=getStoredToken();const results=await Promise.allSettled([AdminService.getFilteredUsers({page:1,size:1},token),AdminService.getAllOrders(token,{page:1,size:5}),AdminService.getAllProducts(token),AdminService.getPendingCancelOrders(token)]);partialError.value=results.some(item=>item.status==="rejected");const data=results.map(item=>item.status==="fulfilled"?item.value.data:null);counts.value={members:totalOf(data[0]),orders:totalOf(data[1]),products:totalOf(data[2]),pending:totalOf(data[3])};recentOrders.value=listOf(data[1]).slice(0,5);loading.value=false};onMounted(loadDashboard);
